-- Generated by tools/schemagen. Do not edit by hand: change the schema there
-- and run `go generate ./tools/schemagen`.
--
-- The three dialects below say the same thing. Writing them by hand is what
-- eighty migrations of this fork do, and every one of them is a place where
-- somebody has to remember three answers to one question.
--
-- What this application adds beside the board: the machine's registries, the
-- sessions, where a card stands on its route. Every foreign
-- key here points at a table the migration before it made.

{{if .sqlite}}
-- A board this machine knows about, whoever's it is. What the app's own
-- tables point at instead of boards(id), which only has the boards
-- served by this process.
--   board_id: The board's own id, on whichever server it lives.
--   source_id: Where the board is. NULL is this machine, which is every board
--     until a desktop attaches to a hosted one.
--   local_board_id: The same board in this process's own table, when it is ours. NULL
--     for a board on a server: that is what makes the key possible at all.
CREATE TABLE `board_ref` (`board_id` varchar NOT NULL, `source_id` varchar NULL, `local_board_id` varchar NULL, `created_at` bigint NOT NULL, PRIMARY KEY (`board_id`), CONSTRAINT `board_ref_local` FOREIGN KEY (`local_board_id`) REFERENCES `boards` (`id`) ON DELETE CASCADE);

-- A card this machine knows about. The row every table keyed on a card
-- points at, so the cascade survives the board being somewhere else.
--   board_id: Which board it is on, and through that which server. Nullable
--     because three of the writers know a card and not its board — a
--     stall, a flow event, a checkout — and the board is filled in by
--     whichever writer knows it.
--   block_id: The same card in this process's own blocks, when it is ours. This
--     is the cascade: the card is deleted, the block goes, this row goes,
--     and everything about the card goes with it.
CREATE TABLE `card_ref` (`card_id` varchar NOT NULL, `board_id` varchar NULL, `block_id` varchar NULL, `created_at` bigint NOT NULL, PRIMARY KEY (`card_id`), CONSTRAINT `card_ref_board` FOREIGN KEY (`board_id`) REFERENCES `board_ref` (`board_id`) ON DELETE CASCADE, CONSTRAINT `card_ref_block` FOREIGN KEY (`block_id`) REFERENCES `blocks` (`id`) ON DELETE CASCADE);

-- Network settings several agents share, so they are edited in one
-- place. Was the `proxies` array in config.json.
--   password: Kept apart from the URL so it is entered raw and masked on screen.
--     Still stored in the clear here, exactly as it was in the settings
--     file: moving it into internal/secrets is its own change.
CREATE TABLE `proxy` (`id` varchar NOT NULL, `name` varchar NOT NULL, `url` text NULL, `no_proxy` text NULL, `ca_cert` text NULL, `username` varchar NULL, `password` text NULL, `created_at` bigint NOT NULL, PRIMARY KEY (`id`));

CREATE UNIQUE INDEX `idx_proxy_name` ON `proxy` (`name`);

-- A named place an agent can work in. Was the `projects` array in
-- config.json; a card points at it by id, which is also the id of the
-- board option offered for it, so a card naming its folder is a card
-- holding an ordinary select value that happens to be a reference.
--   name: A caption, not a key. Renaming it breaks nothing, which is the
--     whole reason the id exists.
--   board_id: The board that offers this folder, and the only one that does.
--     NULL means no board has claimed it — a state the product already
--     has a name and a screen for, which is why a deleted board sets this
--     to NULL rather than taking the registry entry with it.
--   global: «На всех досках»: one entry seen from several boards, which is what
--     makes the mode belong to the pair rather than to the folder.
--   kind: What somebody was promised, not what the folder happens to be:
--     'git' means a repository was demanded and one without git is an
--     error. NULL is the ordinary case and means nobody said.
CREATE TABLE `workspace` (`id` varchar NOT NULL, `name` varchar NOT NULL, `path` text NULL, `board_id` varchar NULL, `global` boolean NOT NULL, `kind` varchar NULL, `base_branch` varchar NULL, `branch_prefix` varchar NULL, `created_at` bigint NOT NULL, PRIMARY KEY (`id`), CONSTRAINT `workspace_offered_on` FOREIGN KEY (`board_id`) REFERENCES `boards` (`id`) ON DELETE SET NULL);

CREATE UNIQUE INDEX `idx_workspace_name` ON `workspace` (`name`);

-- Which board a folder is offered to and how work happens in it there.
-- Keyed by the pair rather than by the folder, because a folder marked
-- «на всех досках» is one entry with a different answer per board: a copy
-- per card where three people work it, a branch in place where one does.
-- Was WorkdirEntry.Modes, a map keyed by board id.
--   mode: NULL means nobody answered, and the machine's own default stands in.
CREATE TABLE `workspace_board` (`workspace_id` varchar NOT NULL, `board_id` varchar NOT NULL, `mode` varchar NULL, PRIMARY KEY (`workspace_id`, `board_id`), CONSTRAINT `workspace_board_workspace` FOREIGN KEY (`workspace_id`) REFERENCES `workspace` (`id`) ON DELETE CASCADE, CONSTRAINT `workspace_board_board` FOREIGN KEY (`board_id`) REFERENCES `boards` (`id`) ON DELETE CASCADE, CONSTRAINT `workspace_board_mode` CHECK (`mode` IS NULL OR `mode` IN ('worktree', 'branch')));

-- A registered agent. Its board account is a row in users, and the two
-- are joined by a key rather than by their names happening to match —
-- which is what made renaming an agent break the crew of every route on
-- every board, silently.
--   name: On screen and in the account's username. No longer a reference.
--   user_id: The board account. NULL until one is made, and NULL again if it is
--     deleted: the registry entry is the machine's and outlives it.
--   settings: env, args, cliArgs, options, autoAllowTools, command,
--     mcpServers. JSON on purpose: this is how to start a process, it
--     points at nothing and nothing joins to it.
CREATE TABLE `agent` (`id` varchar NOT NULL, `name` varchar NOT NULL, `kind` varchar NOT NULL, `user_id` varchar NULL, `proxy_id` varchar NULL, `bin_path` text NULL, `model` varchar NULL, `prompt` text NULL, `settings` text NULL, `created_at` bigint NOT NULL, PRIMARY KEY (`id`), CONSTRAINT `agent_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL, CONSTRAINT `agent_proxy` FOREIGN KEY (`proxy_id`) REFERENCES `proxy` (`id`) ON DELETE SET NULL);

CREATE UNIQUE INDEX `idx_agent_name` ON `agent` (`name`);

-- Where a card's branch is published. Was the `deploys` array in
-- config.json, and a route's stage named it by name.
CREATE TABLE `deploy_target` (`id` varchar NOT NULL, `name` varchar NOT NULL, `ssh_host` varchar NOT NULL, `ssh_user` varchar NULL, `ssh_port` bigint NULL, `ssh_key` text NULL, `base_app` varchar NULL, `base_domain` varchar NULL, `created_at` bigint NOT NULL, PRIMARY KEY (`id`));

CREATE UNIQUE INDEX `idx_deploy_target_name` ON `deploy_target` (`name`);

-- A run of an agent over ACP. One process, one turn, one verdict.
--   card_id: NULL for a run that is about no card — naming a branch is one.
--   column_key: Which column's limit this run counts against. Here rather than in
--     memory because a column's limit is about the board and not about
--     one process: two windows of this app, and one day two machines on
--     one board, all have to be counting the same sessions.
--   finished_at: NULL means the session is still live.
CREATE TABLE `agent_session` (`id` varchar NOT NULL, `card_id` varchar NULL, `board_id` varchar NULL, `agent_kind` varchar NOT NULL, `acp_session_id` varchar NULL, `status` varchar NOT NULL, `column_key` varchar NULL, `cwd` text NULL, `worktree_path` text NULL, `branch` varchar NULL, `started_at` bigint NOT NULL, `finished_at` bigint NULL, `error_text` text NULL, PRIMARY KEY (`id`), CONSTRAINT `agent_session_card` FOREIGN KEY (`card_id`) REFERENCES `card_ref` (`card_id`) ON DELETE CASCADE, CONSTRAINT `agent_session_board` FOREIGN KEY (`board_id`) REFERENCES `board_ref` (`board_id`) ON DELETE CASCADE, CONSTRAINT `agent_session_status` CHECK (`status` IN ('queued', 'running', 'idle', 'waiting_permission', 'done', 'failed', 'cancelled')));

CREATE INDEX `idx_agent_session_card` ON `agent_session` (`card_id`, `started_at`);

-- What happened during a session, in order. The id is a UUIDv7 rather
-- than an autoincrement: v7 sorts by time, so ORDER BY id still means
-- "as it happened" and the three spellings of AUTO_INCREMENT are gone.
-- `seq` went with them — it was the same fact told twice.
CREATE TABLE `session_event` (`id` varchar NOT NULL, `session_id` varchar NOT NULL, `kind` varchar NOT NULL, `payload_json` text NULL, `created_at` bigint NOT NULL, PRIMARY KEY (`id`), CONSTRAINT `session_event_session` FOREIGN KEY (`session_id`) REFERENCES `agent_session` (`id`) ON DELETE CASCADE);

CREATE INDEX `idx_session_event_session` ON `session_event` (`session_id`, `id`);

-- One route event, handled once. `key` was the column's name and is a
-- reserved word in MySQL, so it is `token` — cheaper than backticks in
-- every query for ever.
CREATE TABLE `idempotency` (`token` varchar NOT NULL, `session_id` varchar NULL, `created_at` bigint NOT NULL, PRIMARY KEY (`token`));

CREATE INDEX `idx_idempotency_created` ON `idempotency` (`created_at`);

-- One current reason a card is not moving — not a journal. The reason is
-- true only until somebody fixes what it is about, and a comment would
-- outlive it as noise.
CREATE TABLE `card_stall` (`card_id` varchar NOT NULL, `node_id` varchar NULL, `reason` text NOT NULL, `created_at` bigint NOT NULL, PRIMARY KEY (`card_id`), CONSTRAINT `card_stall_card` FOREIGN KEY (`card_id`) REFERENCES `card_ref` (`card_id`) ON DELETE CASCADE);

-- How much a card's branch holds, in numbers. The diff itself is read
-- from git every time and never from here — this is what the button
-- that opens it is drawn on, and what a board could show per card.
-- Recorded rather than counted when asked, for two reasons: a stage
-- ending folds the working copy away (FoldWorktree) while the question
-- is asked on the stage after that one, and a board asking it per card
-- is a git process per card.
--   base: What the branch was cut from, so a stale row can be told from one
--     about a different base.
--   dirty: Files changed and not committed. Counted apart because they exist
--     only while a working copy does, and the committed half survives it.
CREATE TABLE `card_changes` (`card_id` varchar NOT NULL, `branch` varchar NULL, `base` varchar NULL, `files` bigint NOT NULL, `added` bigint NOT NULL, `removed` bigint NOT NULL, `dirty` bigint NOT NULL, `computed_at` bigint NOT NULL, PRIMARY KEY (`card_id`), CONSTRAINT `card_changes_card` FOREIGN KEY (`card_id`) REFERENCES `card_ref` (`card_id`) ON DELETE CASCADE);

-- A card waiting for its column to free up a place.
--   column_key: board|option — the queue belongs to one column of one board.
CREATE TABLE `stage_queue` (`card_id` varchar NOT NULL, `board_id` varchar NULL, `column_key` varchar NOT NULL, `node_id` varchar NULL, `queued_at` bigint NOT NULL, PRIMARY KEY (`card_id`), CONSTRAINT `stage_queue_card` FOREIGN KEY (`card_id`) REFERENCES `card_ref` (`card_id`) ON DELETE CASCADE, CONSTRAINT `stage_queue_board` FOREIGN KEY (`board_id`) REFERENCES `board_ref` (`board_id`) ON DELETE CASCADE);

CREATE INDEX `idx_stage_queue_column` ON `stage_queue` (`column_key`, `queued_at`);

-- Which setup questions a board has been asked. It is about this machine
-- — the answers are folders and hosts here — so it cannot live in the
-- browser's storage, which the desktop window forgets on every launch.
--   changed_at: Was `at`. AT is a keyword in Postgres and a name not worth having.
CREATE TABLE `board_setup` (`board_id` varchar NOT NULL, `step` varchar NOT NULL, `status` varchar NOT NULL, `changed_at` bigint NOT NULL, PRIMARY KEY (`board_id`, `step`), CONSTRAINT `board_setup_board` FOREIGN KEY (`board_id`) REFERENCES `board_ref` (`board_id`) ON DELETE CASCADE, CONSTRAINT `board_setup_status` CHECK (`status` IN ('pending', 'done', 'skipped', 'offered')));

-- This branch event has already been acted on. Keyed by the workspace
-- rather than by its path: a folder somebody moved used to keep its
-- latches, and MySQL would refuse a path in a key of any real length.
--   marker: The commit the event refers to: the same state seen twice fires once.
CREATE TABLE `vcs_seen` (`workspace_id` varchar NOT NULL, `branch` varchar NOT NULL, `kind` varchar NOT NULL, `marker` varchar NULL, `created_at` bigint NOT NULL, PRIMARY KEY (`workspace_id`, `branch`, `kind`), CONSTRAINT `vcs_seen_workspace` FOREIGN KEY (`workspace_id`) REFERENCES `workspace` (`id`) ON DELETE CASCADE);

-- The directory and the branch one owner holds in one workspace. The
-- owner is a card, or a board for a conversation with no card — two
-- nullable columns rather than one string, because a foreign key cannot
-- point at two tables through one.
--   id: A surrogate, and the one place in this schema where that is right:
--     the natural key would have to include a nullable column, which MySQL
--     and Postgres forbid in a primary key. Uniqueness is stated in the
--     indexes below instead, where a NULL is allowed to differ from a NULL.
--     Nothing outside this application creates a checkout, so no client has
--     to be able to supply the id.
--   board_id: Set for «черновики доски»: a conversation with no card still works
--     somewhere, and that somewhere belongs to the board.
--   path: Where the copy is. Not the workspace's own path — that is on the
--     workspace, and this is the worktree cut from it.
--   base: What the branch was cut from, and therefore what «merged» means.
--   released_at: NULL means the checkout is live.
CREATE TABLE `checkout` (`id` varchar NOT NULL, `workspace_id` varchar NOT NULL, `card_id` varchar NULL, `board_id` varchar NULL, `mode` varchar NOT NULL, `branch` varchar NULL, `path` text NULL, `base` varchar NULL, `created_at` bigint NOT NULL, `released_at` bigint NULL, PRIMARY KEY (`id`), CONSTRAINT `checkout_workspace` FOREIGN KEY (`workspace_id`) REFERENCES `workspace` (`id`) ON DELETE RESTRICT, CONSTRAINT `checkout_card` FOREIGN KEY (`card_id`) REFERENCES `card_ref` (`card_id`) ON DELETE CASCADE, CONSTRAINT `checkout_board` FOREIGN KEY (`board_id`) REFERENCES `board_ref` (`board_id`) ON DELETE CASCADE, CONSTRAINT `checkout_mode` CHECK (`mode` IN ('worktree', 'branch', 'plain')));

CREATE UNIQUE INDEX `idx_checkout_card` ON `checkout` (`workspace_id`, `card_id`);

CREATE UNIQUE INDEX `idx_checkout_board` ON `checkout` (`workspace_id`, `board_id`);

CREATE INDEX `idx_checkout_live` ON `checkout` (`workspace_id`, `released_at`);

-- What a source has already brought. The same letter arriving twice adds
-- to the card it made rather than making a second one.
--   version: The service's own updated/etag: changed means there is something
--     to add.
CREATE TABLE `source_item` (`source` varchar NOT NULL, `external_id` varchar NOT NULL, `version` varchar NULL, `card_id` varchar NULL, `created_at` bigint NOT NULL, `updated_at` bigint NOT NULL, PRIMARY KEY (`source`, `external_id`), CONSTRAINT `source_item_card` FOREIGN KEY (`card_id`) REFERENCES `card_ref` (`card_id`) ON DELETE SET NULL);

CREATE INDEX `idx_source_item_card` ON `source_item` (`card_id`);

-- Why nothing happened — the only question anybody asks of a source.
-- Deleting the card it produced does not delete the line: what a source
-- decided is a fact about the source.
CREATE TABLE `source_event` (`id` varchar NOT NULL, `source` varchar NOT NULL, `external_id` varchar NULL, `rule` varchar NULL, `outcome` varchar NOT NULL, `card_id` varchar NULL, `detail` text NULL, `created_at` bigint NOT NULL, PRIMARY KEY (`id`), CONSTRAINT `source_event_card` FOREIGN KEY (`card_id`) REFERENCES `card_ref` (`card_id`) ON DELETE SET NULL, CONSTRAINT `source_event_outcome` CHECK (`outcome` IN ('created', 'commented', 'inbox', 'dropped', 'failed', 'skipped')));

CREATE INDEX `idx_source_event_source` ON `source_event` (`source`, `id`);

-- What a board's cards are about, written by an agent from their titles.
-- It is what the inbox is sorted by beside the board's own description:
-- a description says what a board was made for, and the cards say what
-- it is used for. Kept here rather than on the board because it is this
-- machine's reading of the board, redone whenever the cards change.
--   fingerprint: A hash of the cards the summary was written from. A different one
--     means the summary is about cards the board no longer holds.
CREATE TABLE `board_summary` (`board_id` varchar NOT NULL, `summary` text NOT NULL, `card_count` bigint NOT NULL, `fingerprint` varchar NOT NULL, `updated_at` bigint NOT NULL, PRIMARY KEY (`board_id`), CONSTRAINT `board_summary_board` FOREIGN KEY (`board_id`) REFERENCES `board_ref` (`board_id`) ON DELETE CASCADE);

-- Where the sorter put a card from the inbox, and why. A card that
-- turns up on a board nobody carried it to is the question this answers.
-- Both keys SET NULL: the decision is a fact about the sorter and
-- outlives the card and the board.
--   card_title: What the card was called, so the log still reads once it is gone.
--   board_id: Where it went. NULL for a card left in the inbox.
CREATE TABLE `inbox_sort` (`id` varchar NOT NULL, `card_id` varchar NULL, `card_title` text NULL, `board_id` varchar NULL, `outcome` varchar NOT NULL, `reason` text NULL, `created_at` bigint NOT NULL, PRIMARY KEY (`id`), CONSTRAINT `inbox_sort_card` FOREIGN KEY (`card_id`) REFERENCES `card_ref` (`card_id`) ON DELETE SET NULL, CONSTRAINT `inbox_sort_board` FOREIGN KEY (`board_id`) REFERENCES `board_ref` (`board_id`) ON DELETE SET NULL, CONSTRAINT `inbox_sort_outcome` CHECK (`outcome` IN ('moved', 'kept', 'failed')));
{{end}}

{{if .mysql}}
-- Where a card's branch is published. Was the `deploys` array in
-- config.json, and a route's stage named it by name.
CREATE TABLE `deploy_target` (`id` varchar(36) NOT NULL, `name` varchar(100) NOT NULL, `ssh_host` varchar(255) NOT NULL, `ssh_user` varchar(64) NULL, `ssh_port` bigint NULL, `ssh_key` text NULL, `base_app` varchar(100) NULL, `base_domain` varchar(255) NULL, `created_at` bigint NOT NULL, PRIMARY KEY (`id`), UNIQUE INDEX `idx_deploy_target_name` (`name`)) CHARSET utf8mb4 COLLATE utf8mb4_general_ci;

-- One route event, handled once. `key` was the column's name and is a
-- reserved word in MySQL, so it is `token` — cheaper than backticks in
-- every query for ever.
CREATE TABLE `idempotency` (`token` varchar(255) NOT NULL, `session_id` varchar(36) NULL, `created_at` bigint NOT NULL, PRIMARY KEY (`token`), INDEX `idx_idempotency_created` (`created_at`)) CHARSET utf8mb4 COLLATE utf8mb4_general_ci;

-- Network settings several agents share, so they are edited in one
-- place. Was the `proxies` array in config.json.
--   password: Kept apart from the URL so it is entered raw and masked on screen.
--     Still stored in the clear here, exactly as it was in the settings
--     file: moving it into internal/secrets is its own change.
CREATE TABLE `proxy` (`id` varchar(36) NOT NULL, `name` varchar(100) NOT NULL, `url` text NULL, `no_proxy` text NULL, `ca_cert` text NULL, `username` varchar(100) NULL, `password` text NULL, `created_at` bigint NOT NULL, PRIMARY KEY (`id`), UNIQUE INDEX `idx_proxy_name` (`name`)) CHARSET utf8mb4 COLLATE utf8mb4_general_ci;

-- A registered agent. Its board account is a row in users, and the two
-- are joined by a key rather than by their names happening to match —
-- which is what made renaming an agent break the crew of every route on
-- every board, silently.
--   name: On screen and in the account's username. No longer a reference.
--   user_id: The board account. NULL until one is made, and NULL again if it is
--     deleted: the registry entry is the machine's and outlives it.
--   settings: env, args, cliArgs, options, autoAllowTools, command,
--     mcpServers. JSON on purpose: this is how to start a process, it
--     points at nothing and nothing joins to it.
CREATE TABLE `agent` (`id` varchar(36) NOT NULL, `name` varchar(100) NOT NULL, `kind` varchar(32) NOT NULL, `user_id` varchar(36) NULL, `proxy_id` varchar(36) NULL, `bin_path` text NULL, `model` varchar(100) NULL, `prompt` text NULL, `settings` text NULL, `created_at` bigint NOT NULL, PRIMARY KEY (`id`), UNIQUE INDEX `idx_agent_name` (`name`), CONSTRAINT `agent_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL, CONSTRAINT `agent_proxy` FOREIGN KEY (`proxy_id`) REFERENCES `proxy` (`id`) ON DELETE SET NULL) CHARSET utf8mb4 COLLATE utf8mb4_general_ci;

-- A board this machine knows about, whoever's it is. What the app's own
-- tables point at instead of boards(id), which only has the boards
-- served by this process.
--   board_id: The board's own id, on whichever server it lives.
--   source_id: Where the board is. NULL is this machine, which is every board
--     until a desktop attaches to a hosted one.
--   local_board_id: The same board in this process's own table, when it is ours. NULL
--     for a board on a server: that is what makes the key possible at all.
CREATE TABLE `board_ref` (`board_id` varchar(36) NOT NULL, `source_id` varchar(64) NULL, `local_board_id` varchar(36) NULL, `created_at` bigint NOT NULL, PRIMARY KEY (`board_id`), CONSTRAINT `board_ref_local` FOREIGN KEY (`local_board_id`) REFERENCES `boards` (`id`) ON DELETE CASCADE) CHARSET utf8mb4 COLLATE utf8mb4_general_ci;

-- A card this machine knows about. The row every table keyed on a card
-- points at, so the cascade survives the board being somewhere else.
