--   base: What the branch was cut from, and therefore what «merged» means.
--   released_at: NULL means the checkout is live.
CREATE UNIQUE INDEX "idx_checkout_card" ON "checkout" ("workspace_id", "card_id");

-- The directory and the branch one owner holds in one workspace. The
-- owner is a card, or a board for a conversation with no card — two
-- nullable columns rather than one string, because a foreign key cannot
-- point at two tables through one.
--   id: A surrogate, and the one place in this schema where that is right:
--     the natural key would have to include a nullable column, which MySQL
--     and Postgres forbid in a primary key. Uniqueness is stated in the
--     indexes below instead, where a NULL is allowed to differ from a NULL.
--     Nothing outside this application creates a checkout, so no client has
--     to be able to supply the id.
--   board_id: Set for «черновики доски»: a conversation with no card still works
--     somewhere, and that somewhere belongs to the board.
--   path: Where the copy is. Not the workspace's own path — that is on the
--     workspace, and this is the worktree cut from it.
--   base: What the branch was cut from, and therefore what «merged» means.
--   released_at: NULL means the checkout is live.
CREATE UNIQUE INDEX "idx_checkout_board" ON "checkout" ("workspace_id", "board_id");

-- The directory and the branch one owner holds in one workspace. The
-- owner is a card, or a board for a conversation with no card — two
-- nullable columns rather than one string, because a foreign key cannot
-- point at two tables through one.
--   id: A surrogate, and the one place in this schema where that is right:
--     the natural key would have to include a nullable column, which MySQL
--     and Postgres forbid in a primary key. Uniqueness is stated in the
--     indexes below instead, where a NULL is allowed to differ from a NULL.
--     Nothing outside this application creates a checkout, so no client has
--     to be able to supply the id.
--   board_id: Set for «черновики доски»: a conversation with no card still works
--     somewhere, and that somewhere belongs to the board.
--   path: Where the copy is. Not the workspace's own path — that is on the
--     workspace, and this is the worktree cut from it.
--   base: What the branch was cut from, and therefore what «merged» means.
--   released_at: NULL means the checkout is live.
CREATE INDEX "idx_checkout_live" ON "checkout" ("workspace_id", "released_at");

-- Where the sorter put a card from the inbox, and why. A card that
-- turns up on a board nobody carried it to is the question this answers.
-- Both keys SET NULL: the decision is a fact about the sorter and
-- outlives the card and the board.
--   card_title: What the card was called, so the log still reads once it is gone.
--   board_id: Where it went. NULL for a card left in the inbox.
CREATE TABLE "inbox_sort" ("id" character varying(36) NOT NULL, "card_id" character varying(36) NULL, "card_title" text NULL, "board_id" character varying(36) NULL, "outcome" character varying(16) NOT NULL, "reason" text NULL, "created_at" bigint NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "inbox_sort_card" FOREIGN KEY ("card_id") REFERENCES "card_ref" ("card_id") ON DELETE SET NULL, CONSTRAINT "inbox_sort_board" FOREIGN KEY ("board_id") REFERENCES "board_ref" ("board_id") ON DELETE SET NULL, CONSTRAINT "inbox_sort_outcome" CHECK ("outcome" IN ('moved', 'kept', 'failed')));

-- What happened during a session, in order. The id is a UUIDv7 rather
-- than an autoincrement: v7 sorts by time, so ORDER BY id still means
-- "as it happened" and the three spellings of AUTO_INCREMENT are gone.
-- `seq` went with them — it was the same fact told twice.
CREATE TABLE "session_event" ("id" character varying(36) NOT NULL, "session_id" character varying(36) NOT NULL, "kind" character varying(32) NOT NULL, "payload_json" text NULL, "created_at" bigint NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "session_event_session" FOREIGN KEY ("session_id") REFERENCES "agent_session" ("id") ON DELETE CASCADE);

-- What happened during a session, in order. The id is a UUIDv7 rather
-- than an autoincrement: v7 sorts by time, so ORDER BY id still means
-- "as it happened" and the three spellings of AUTO_INCREMENT are gone.
-- `seq` went with them — it was the same fact told twice.
CREATE INDEX "idx_session_event_session" ON "session_event" ("session_id", "id");

-- Why nothing happened — the only question anybody asks of a source.
-- Deleting the card it produced does not delete the line: what a source
-- decided is a fact about the source.
CREATE TABLE "source_event" ("id" character varying(36) NOT NULL, "source" character varying(100) NOT NULL, "external_id" character varying(255) NULL, "rule" character varying(100) NULL, "outcome" character varying(16) NOT NULL, "card_id" character varying(36) NULL, "detail" text NULL, "created_at" bigint NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "source_event_card" FOREIGN KEY ("card_id") REFERENCES "card_ref" ("card_id") ON DELETE SET NULL, CONSTRAINT "source_event_outcome" CHECK ("outcome" IN ('created', 'commented', 'inbox', 'dropped', 'failed', 'skipped')));

-- Why nothing happened — the only question anybody asks of a source.
-- Deleting the card it produced does not delete the line: what a source
-- decided is a fact about the source.
CREATE INDEX "idx_source_event_source" ON "source_event" ("source", "id");

-- What a source has already brought. The same letter arriving twice adds
-- to the card it made rather than making a second one.
--   version: The service's own updated/etag: changed means there is something
--     to add.
CREATE TABLE "source_item" ("source" character varying(100) NOT NULL, "external_id" character varying(255) NOT NULL, "version" character varying(255) NULL, "card_id" character varying(36) NULL, "created_at" bigint NOT NULL, "updated_at" bigint NOT NULL, PRIMARY KEY ("source", "external_id"), CONSTRAINT "source_item_card" FOREIGN KEY ("card_id") REFERENCES "card_ref" ("card_id") ON DELETE SET NULL);

-- What a source has already brought. The same letter arriving twice adds
-- to the card it made rather than making a second one.
--   version: The service's own updated/etag: changed means there is something
--     to add.
CREATE INDEX "idx_source_item_card" ON "source_item" ("card_id");

-- A card waiting for its column to free up a place.
--   column_key: board|option — the queue belongs to one column of one board.
CREATE TABLE "stage_queue" ("card_id" character varying(36) NOT NULL, "board_id" character varying(36) NULL, "column_key" character varying(128) NOT NULL, "node_id" character varying(64) NULL, "queued_at" bigint NOT NULL, PRIMARY KEY ("card_id"), CONSTRAINT "stage_queue_card" FOREIGN KEY ("card_id") REFERENCES "card_ref" ("card_id") ON DELETE CASCADE, CONSTRAINT "stage_queue_board" FOREIGN KEY ("board_id") REFERENCES "board_ref" ("board_id") ON DELETE CASCADE);

-- A card waiting for its column to free up a place.
--   column_key: board|option — the queue belongs to one column of one board.
CREATE INDEX "idx_stage_queue_column" ON "stage_queue" ("column_key", "queued_at");

-- This branch event has already been acted on. Keyed by the workspace
-- rather than by its path: a folder somebody moved used to keep its
-- latches, and MySQL would refuse a path in a key of any real length.
--   marker: The commit the event refers to: the same state seen twice fires once.
CREATE TABLE "vcs_seen" ("workspace_id" character varying(36) NOT NULL, "branch" character varying(255) NOT NULL, "kind" character varying(32) NOT NULL, "marker" character varying(64) NULL, "created_at" bigint NOT NULL, PRIMARY KEY ("workspace_id", "branch", "kind"), CONSTRAINT "vcs_seen_workspace" FOREIGN KEY ("workspace_id") REFERENCES "workspace" ("id") ON DELETE CASCADE);

-- Which board a folder is offered to and how work happens in it there.
-- Keyed by the pair rather than by the folder, because a folder marked
-- «на всех досках» is one entry with a different answer per board: a copy
-- per card where three people work it, a branch in place where one does.
-- Was WorkdirEntry.Modes, a map keyed by board id.
--   mode: NULL means nobody answered, and the machine's own default stands in.
CREATE TABLE "workspace_board" ("workspace_id" character varying(36) NOT NULL, "board_id" character varying(36) NOT NULL, "mode" character varying(16) NULL, PRIMARY KEY ("workspace_id", "board_id"), CONSTRAINT "workspace_board_workspace" FOREIGN KEY ("workspace_id") REFERENCES "workspace" ("id") ON DELETE CASCADE, CONSTRAINT "workspace_board_board" FOREIGN KEY ("board_id") REFERENCES "boards" ("id") ON DELETE CASCADE, CONSTRAINT "workspace_board_mode" CHECK ("mode" IS NULL OR "mode" IN ('worktree', 'branch')));
{{end}}
